SELECT jsonb_build_object('columns',(SELECT jsonb_agg(column_name) FROM information_schema.columns WHERE table_name='tb_evento_corridas'),'events',(SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT id_evento,nome_evento,data_inicial::date,data_final::date,ativo,(SELECT coalesce(jsonb_agg(to_jsonb(c)),'[]') FROM tb_conta_eventos c WHERE c.id_evento=e.id_evento) contas FROM tb_evento_corridas e WHERE id_evento IN (48783,48766,45413,47688,46865))x))::text payload